17	/// Which of a module's catalog blocks are active for a given option
18	/// selection — ported case-by-case from zoia_lib `patch_binary.py`
19	/// `_calc_blocks`. Unlike upstream, no min/max block-count error is
20	/// raised: device-written patches are truth, and three factory Euroburo
21	/// patches fail upstream's minimum check.
22	enum BlockLayout {
23	    /// Resolves the module's option bytes to selected values, in catalog
24	    /// option order (the byte order in the binary).
25	    static func selectedOptions(spec: ModuleSpec, optionBytes: [UInt8]) throws -> [OptionValue] {
26	        var selected: [OptionValue] = []
27	        var byteIndex = 0
28	        for option in spec.options where !option.key.isEmpty {
29	            let byte = byteIndex < optionBytes.count ? Int(optionBytes[byteIndex]) : 0
30	            guard byte < option.values.count else {
31	                throw BlockLayoutError.optionByteOutOfRange(
32	                    module: spec.name, option: option.key, byte: byte,
33	                    valueCount: option.values.count)
34	            }
35	            selected.append(option.values[byte])
36	            byteIndex += 1
37	        }
38	        return selected
39	    }
40	
41	    static func activeBlocks(spec: ModuleSpec, optionBytes: [UInt8], version: Int) throws -> [BlockSpec] {
42	        let opt = try selectedOptions(spec: spec, optionBytes: optionBytes)
43	        return try activeBlocks(spec: spec, options: opt, version: version)
44	    }
45	
46	    // swiftlint:disable:next cyclomatic_complexity function_body_length
47	    static func activeBlocks(spec: ModuleSpec, options opt: [OptionValue], version: Int) throws -> [BlockSpec] {
48	        let d = spec.blocks
49	        var blocks: [BlockSpec] = []
50	
51	        // Selected option value as text ("" when absent) or int (0 when
52	        // absent or non-numeric) — mirrors Python string/int comparisons.
53	        func s(_ i: Int) -> String {
54	            guard i < opt.count, case .text(let t) = opt[i] else { return "" }
55	            return t
56	        }
57	        func n(_ i: Int) -> Int {
58	            guard i < opt.count, case .number(let v) = opt[i] else { return 0 }
59	            return Int(v)
60	        }
61	        func add(_ index: Int) throws {
62	            guard index >= 0, index < d.count else {
63	                throw BlockLayoutError.blockIndexOutOfRange(
64	                    module: spec.name, index: index, blockCount: d.count)
65	            }
66	            blocks.append(d[index])
67	        }
68	        func addAll(_ indices: [Int]) throws { for i in indices { try add(i) } }
69	        func count(_ n: Int, _ body: (Int) throws -> Void) rethrows {
70	            var i = 1
71	            while i <= n { try body(i); i += 1 }
72	        }
73	
74	        switch spec.id {
75	        case 0: // sv_filter
76	            try addAll([0, 1, 2])
77	            for (optIndex, blockIndex) in zip(opt.indices, 3..<6) where s(optIndex) == "on" {
78	                try add(blockIndex)
79	            }
80	        case 1: // audio_input
81	            switch s(0) {
82	            case "left": try add(0)
83	            case "right": try add(1)
84	            default: try addAll([0, 1])
85	            }
86	        case 2: // audio_output
87	            switch s(1) {
88	            case "left": try add(0)
89	            case "right": try add(1)
90	            default: try addAll([0, 1])
91	            }
92	            if s(0) == "on" { try add(2) }
93	        case 4: // sequencer
