10	private func corpusURL(_ relPath: String) throws -> URL {
11	    let bundle = Bundle(for: CorpusLocator.self)
12	    let root = try #require(bundle.resourceURL?.appendingPathComponent("Corpus"),
13	                            "Corpus folder missing from test bundle")
14	    return root.appendingPathComponent(relPath)
15	}
