17	private func sequencerEntries(_ relPath: String) throws -> [ZoiaModuleEntry] {
18	    let patch = try ZoiaPatchBinary.decode(Data(contentsOf: corpusURL(relPath)))
19	    return patch.modules.filter { $0.typeID == 4 }
20	}
